137	fn complete_arg(
138	    arg: &clap_lex::ParsedArg<'_>,
139	    cmd: &clap::Command,
140	    current_dir: Option<&std::path::Path>,
141	    pos_index: usize,
142	    is_escaped: bool,
143	    state: ParseState<'_>,
144	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
145	    debug!(
146	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
147	        arg,
148	        cmd.get_name(),
149	        current_dir,
150	        pos_index,
151	        state
152	    );
153	    let mut completions = Vec::<CompletionCandidate>::new();
154	
155	    match state {
156	        ParseState::ValueDone => {
157	            if let Ok(value) = arg.to_value() {
158	                completions.extend(complete_subcommand(value, cmd));
159	            }
160	
161	            if let Some(positional) = cmd
162	                .get_positionals()
163	                .find(|p| p.get_index() == Some(pos_index))
164	            {
165	                completions.extend(complete_arg_value(
166	                    arg.to_value(),
167	                    positional,
168	                    current_dir,
169	                    0,
170	                ));
171	            }
172	            if !is_escaped {
173	                completions.extend(complete_option(arg, cmd, current_dir));
174	            }
175	        }
176	        ParseState::Pos((_, num_arg)) => {
177	            if let Some(positional) = cmd
178	                .get_positionals()
179	                .find(|p| p.get_index() == Some(pos_index))
180	            {
181	                completions.extend(complete_arg_value(
182	                    arg.to_value(),
183	                    positional,
184	                    current_dir,
185	                    num_arg.saturating_sub(1),
186	                ));
187	                if !is_escaped
188	                    && positional
189	                        .get_num_args()
190	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
191	                {
192	                    completions.extend(complete_option(arg, cmd, current_dir));
193	                }
194	            }
195	        }
196	        ParseState::Opt((opt, count)) => {
197	            completions.extend(complete_arg_value(
198	                arg.to_value(),
199	                opt,
200	                current_dir,
201	                count.saturating_sub(1),
202	            ));
203	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
204	            if count > min {
205	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
206	                completions.extend(complete_arg(
207	                    arg,
208	                    cmd,
209	                    current_dir,
210	                    pos_index,
211	                    is_escaped,
212	                    ParseState::ValueDone,
213	                )?);
214	            }
215	        }
216	    }
217	    if completions.iter().any(|a| !a.is_hide_set()) {
218	        completions.retain(|a| !a.is_hide_set());
219	    }
220	    let mut seen_ids = std::collections::HashSet::new();
221	    completions.retain(move |a| {
222	        if let Some(id) = a.get_id().cloned() {
223	            seen_ids.insert(id)
224	        } else {
225	            true
226	        }
227	    });
228	
229	    let mut tags = Vec::new();
230	    for candidate in &completions {
231	        let tag = candidate.get_tag().cloned();
232	        if !tags.contains(&tag) {
233	            tags.push(tag);
234	        }
235	    }
236	    completions.sort_by_key(|c| {
237	        (
238	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
239	            c.get_display_order(),
240	        )
241	    });
242	
243	    Ok(completions)
244	}
245	
246	fn complete_option(
247	    arg: &clap_lex::ParsedArg<'_>,
248	    cmd: &clap::Command,
249	    current_dir: Option<&std::path::Path>,
250	) -> Vec<CompletionCandidate> {
251	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
252	    let mut completions = Vec::<CompletionCandidate>::new();
253	    if arg.is_empty() {
254	        completions.extend(longs_and_visible_aliases(cmd));
255	        completions.extend(hidden_longs_aliases(cmd));
256	
257	        let dash_or_arg = if arg.is_empty() {
258	            "-".into()
259	        } else {
260	            arg.to_value_os().to_string_lossy()
261	        };
262	        completions.extend(
263	            shorts_and_visible_aliases(cmd)
264	                .into_iter()
265	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
266	        );
267	    } else if arg.is_stdio() {
268	        // HACK: Assuming knowledge of is_stdio
269	        let dash_or_arg = if arg.is_empty() {
270	            "-".into()
271	        } else {
272	            arg.to_value_os().to_string_lossy()
273	        };
274	        completions.extend(
275	            shorts_and_visible_aliases(cmd)
276	                .into_iter()
277	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
278	        );
279	
280	        completions.extend(longs_and_visible_aliases(cmd));
281	        completions.extend(hidden_longs_aliases(cmd));
282	    } else if arg.is_escape() {
283	        // HACK: Assuming knowledge of is_escape
284	        completions.extend(longs_and_visible_aliases(cmd));
285	        completions.extend(hidden_longs_aliases(cmd));
286	    } else if let Some((flag, value)) = arg.to_long() {
287	        if let Ok(flag) = flag {
288	            if let Some(value) = value {
289	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
290	                    completions.extend(
291	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
292	                            .into_iter()
293	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
294	                    );
295	                }
296	            } else {
297	                completions.extend(
298	                    longs_and_visible_aliases(cmd)
299	                        .into_iter()
300	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
301	                );
302	                completions.extend(
303	                    hidden_longs_aliases(cmd)
304	                        .into_iter()
305	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
306	                );
307	            }
308	        }
309	    } else if let Some(short) = arg.to_short() {
310	        if !short.is_negative_number() {
311	            // Find the first takes_values option.
312	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
313	
314	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
315	            if let Some(opt) = takes_value_opt {
316	                let mut peek_short = short.clone();
317	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
318	                    short.next_flag();
319	                    true
320	                } else {
321	                    false
322	                };
323	
324	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
325	                completions.extend(
326	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
327	                        .into_iter()
328	                        .map(|comp| {
329	                            let sep = if has_equal { "=" } else { "" };
330	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
331	                        }),
332	                );
333	            } else {
334	                completions.extend(
335	                    shorts_and_visible_aliases(cmd)
336	                        .into_iter()
337	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
338	                );
339	            }
340	        }
341	    }
342	    debug!("complete_option: completions={completions:?}");
343	    completions
344	}
345	
346	fn complete_arg_value(
347	    value: Result<&str, &OsStr>,
348	    arg: &clap::Arg,
349	    current_dir: Option<&std::path::Path>,
350	    arg_index: usize,
351	) -> Vec<CompletionCandidate> {
352	    let mut values = Vec::new();
353	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
354	
355	    let (prefix, value) =
356	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
357	
358	    let value_os = match value {
359	        Ok(value) => OsStr::new(value),
360	        Err(value_os) => value_os,
361	    };
362	
363	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
364	        values.extend(completer.complete_at(arg_index, value_os));
365	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
366	        values.extend(complete_value_candidates(
367	            value_os,
368	            completer.value_candidates(),
369	        ));
370	    } else if let Some(possible_values) = possible_values(arg) {
371	        if let Ok(value) = value {
372	            values.extend(complete_candidates_str(
373	                value,
374	                possible_value_candidates(possible_values),
375	            ));
376	        }
377	    } else {
378	        match arg.get_value_hint() {
379	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
380	                // Should not complete
381	            }
382	            clap::ValueHint::AnyPath => {
383	                values.extend(complete_path(value_os, current_dir, &|_| true));
384	            }
385	            clap::ValueHint::FilePath => {
386	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
387	            }
388	            clap::ValueHint::DirPath => {
389	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
390	            }
391	            clap::ValueHint::ExecutablePath => {
392	                use is_executable::IsExecutable;
393	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
394	            }
395	            clap::ValueHint::CommandName
396	            | clap::ValueHint::CommandString
397	            | clap::ValueHint::CommandWithArguments
398	            | clap::ValueHint::Username
399	            | clap::ValueHint::Hostname
400	            | clap::ValueHint::Url
401	            | clap::ValueHint::EmailAddress => {
402	                // No completion implementation
403	            }
404	            _ => {
405	                // Safe-ish fallback
406	                values.extend(complete_path(value_os, current_dir, &|_| true));
407	            }
408	        }
409	
410	        values.sort();
411	    }
412	
413	    if let Some(prefix) = prefix {
414	        values = values
415	            .into_iter()
416	            .map(|comp| comp.add_prefix(prefix))
417	            .collect();
418	    }
419	    values = values
420	        .into_iter()
421	        .map(|comp| {
422	            if comp.get_tag().is_some() {
423	                comp
424	            } else {
425	                comp.tag(Some(arg.to_string().into()))
426	            }
427	        })
428	        .collect();
429	
430	    debug!("complete_arg_value: values={values:?}");
431	    values
432	}
433	
434	fn rsplit_delimiter<'s, 'o>(
435	    value: Result<&'s str, &'o OsStr>,
436	    delimiter: Option<char>,
437	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
438	    let delimiter = delimiter?;
439	    let value = value.ok()?;
440	    let pos = value.rfind(delimiter)?;
441	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
442	    Some((Some(prefix), Ok(value)))
443	}
444	
445	fn complete_value_candidates(
446	    value: &OsStr,
447	    completer: &dyn ValueCandidates,
448	) -> Vec<CompletionCandidate> {
449	    debug!("complete_value_candidates: value={value:?}");
450	
451	    let mut values = completer.candidates();
452	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
453	    values
454	}
455	
456	fn complete_candidates_str(
457	    value: &str,
458	    mut values: Vec<CompletionCandidate>,
459	) -> Vec<CompletionCandidate> {
460	    debug!("complete_candidates_str: value={value:?}");
461	
462	    values.retain(|comp| comp.get_value().starts_with(value));
463	    values
464	}
465	
466	fn complete_value_candidates_str(
467	    value: &str,
468	    completer: &dyn ValueCandidates,
469	) -> Vec<CompletionCandidate> {
470	    debug!("complete_value_candidates_str: value={value:?}");
471	
472	    complete_candidates_str(value, completer.candidates())
473	}
474	
475	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
476	    debug!(
477	        "complete_subcommand: cmd={:?}, value={:?}",
478	        cmd.get_name(),
479	        value
480	    );
481	
482	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
483	        .into_iter()
484	        .filter(|x| x.get_value().starts_with(value))
485	        .collect();
486	    if cmd.is_allow_external_subcommands_set() {
487	        let external_completer = cmd.get::<SubcommandCandidates>();
488	        if let Some(completer) = external_completer {
489	            scs.extend(complete_value_candidates_str(
490	                value,
491	                completer.value_candidates(),
492	            ));
493	        }
494	    }
495	
496	    scs.sort();
497	    scs.dedup();
498	    scs
499	}
